fields.InputDefinition:
{
  "goal": "Open the Chat application and wait for the workspace. In the sidebar, open the '...' (Options) menu at the top of the conversation list and choose 'Group by folder'. Confirm the list restructures to show a 'Folders' section (with a 'New Folder' / folder-plus affordance) and an 'Ungrouped'/'Messages' section. Optionally click the New Folder button and confirm a folder-creation dialog appears. Then use the menu again to switch back to 'Show as flat list' and confirm the flat 'Messages' list returns. The layout switching between folder-grouped and flat is success. Pages can take 10-30s to load in this resource-constrained environment — wait, don't navigate away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}
